namespace courtlogic {

namespace {

// The two clamps and the wire's clamp must all say 90 minutes. They are
// separate constants on purpose — RelayGuard must not take the decoder's word
// for a duration — so the agreement is asserted rather than assumed.
static_assert(kRelayHardCapMs == static_cast<uint32_t>(proto::kRelayHardCapSeconds) * 1000UL,
              "the relay hard cap and the protocol's wire clamp have drifted apart");

// hal::IButtonPort numbers courts 0-3 and duration slots 4-7; proto::Key spells
// the same eight in the same order. The `!BTN` frame is built by casting one to
// the other, so the two orders being identical is load-bearing.
static_assert(static_cast<uint8_t>(proto::Key::CourtA) == hal::kCourtButtonBase,
              "proto::Key and hal button channels must agree on where the courts start");
static_assert(static_cast<uint8_t>(proto::Key::Slot1) == hal::kDurationButtonBase,
              "proto::Key and hal button channels must agree on where the duration slots start");
static_assert(static_cast<uint8_t>(proto::Key::Slot4) + 1U == hal::kButtonCount,
              "proto::Key and hal button channels must cover the same eight buttons");

/// Decimal parse of an argument the decoder has already validated and clamped.
///
/// Saturating rather than wrapping, and stopping at the first non-digit. Both
/// are belt-and-braces: buildFrame() rejects a non-numeric duration and rewrites
/// the argument with the clamped value, so neither branch is reachable from the
/// wire. They are here because RelayGuard's independence is only real if
/// nothing on this path assumes the bytes came from a well-behaved peer.
uint32_t parseU32(const char* text) {
  uint32_t value = 0U;
  for (size_t i = 0U; text[i] != '\0'; ++i) {
    const char c = text[i];
    if (c < '0' || c > '9') {
      break;
    }
    const uint32_t digit = static_cast<uint32_t>(c - '0');
    if (value > (UINT32_MAX - digit) / 10U) {
      return UINT32_MAX;
    }
    value = value * 10U + digit;
  }
  return value;
}

} // namespace

CourtBox::CourtBox(const CourtPorts& ports, proto::LegacyDialect legacy)
    : display_(ports.display), scanner_(ports.scanner), bridge_(ports.bridge), clock_(ports.clock),
      relays_(ports.relay), panel_(ports.buttons), scan_(), auth_(), rx_(proto::Link::Downlink, legacy),
      uptime_(), stateDue_(), scanFeedback_(), lastMask_(0U), overrunPending_(false), txBuf_(),
      txDropped_(0U), rxErrors_(0U), unauthorised_(0U), oversizeScans_(0U) {
}

void CourtBox::begin() {
  relays_.allOff();
  auth_.disarm();
  scan_.reset();
  rx_.reset();
  scanFeedback_.disarm();
  const uint32_t now = clock_.nowMs();
  uptime_.seed(now);
  stateDue_.arm(now, kStateIntervalMs);
  lastMask_ = 0U;
  showIdle();
}

void CourtBox::poll() {
  // Once. Every sub-step is evaluated against the same instant; see the header.
  const uint32_t now = clock_.nowMs();
  uptime_.tick(now);

  drainBridge(now);
  drainScanner(now);
  pollButtons(now);
  releaseExpired(now);
  noteAuthLapse(now);
  expireScanFeedback(now);
  flushOverrun();
  publishState(now);
}

// --- one pass --------------------------------------------------------------

void CourtBox::drainBridge(uint32_t nowMs) {
  uint8_t byte = 0U;
  for (uint16_t i = 0U; i < kBytesPerPass && bridge_.read(byte); ++i) {
    if (!rx_.feed(static_cast<char>(byte))) {
      continue;
    }
    proto::Decoder::Result result;
    while (rx_.pop(result)) {
      handleResult(result, nowMs);
    }
  }
}

void CourtBox::drainScanner(uint32_t nowMs) {
  uint8_t byte = 0U;
  for (uint16_t i = 0U; i < kBytesPerPass && scanner_.read(byte); ++i) {
    if (!scan_.feed(byte)) {
      continue;
    }
    const proto::Frame frame = proto::Frame::scan(scan_.code());
    if (frame.empty()) {
      // Frame::scan() refuses a code that does not fit rather than truncating
      // it, and so does ScanAssembler. Both refusals are counted here because a
      // scanner that has started emitting long payloads is a fault an admin
      // needs to see, not a member behaving oddly.
      if (oversizeScans_ < UINT16_MAX) {
        ++oversizeScans_;
      }
      continue;
    }
    static_cast<void>(sendFrame(frame));
    // Painted whether or not the frame got out. A full TX ring IS the dead-ESP
    // case, and that is exactly when the member most needs to see that the
    // scanner heard them — see kScanFeedbackLine1.
    paintRow(0U, kScanFeedbackLine1);
    paintRow(1U, "");
    scanFeedback_.arm(nowMs, kScanFeedbackMs);
  }
}

void CourtBox::expireScanFeedback(uint32_t nowMs) {
  if (scanFeedback_.expired(nowMs)) {
    scanFeedback_.disarm();
    showIdle();
  }
}

void CourtBox::pollButtons(uint32_t nowMs) {
  const uint8_t pressed = panel_.poll(nowMs);
  if (pressed == 0U) {
    return;
  }
  if (!auth_.allows(nowMs)) {
    // Dropped, not queued. A press held until the next authorisation window
    // opens would fire a relay on the NEXT member's scan, which is precisely
    // the unexpiring-flag defect this window exists to close.
    if (unauthorised_ < UINT16_MAX) {
      ++unauthorised_;
    }
    return;
  }
  for (uint8_t i = 0U; i < hal::kButtonCount; ++i) {
    if ((pressed & buttonBit(i)) == 0U) {
      continue;
    }
    static_cast<void>(sendFrame(proto::Frame::btn(static_cast<proto::Key>(i))));
  }
}

void CourtBox::releaseExpired(uint32_t nowMs) {
  const uint8_t released = relays_.tick(nowMs);
  if (released == 0U) {
    return;
  }
  for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
    if ((released & relayBit(i)) != 0U) {
      sendCourtEvent("AUTOOFF", static_cast<proto::Court>(i));
    }
  }
  // The relay is already open by this point. Publishing the new state is how
  // the bridge finds out when the event above did NOT get through: the bridge
  // reconciles its held courts against every `!STATE` mask (bridgelogic/
  // StateReconcile), and this one goes out whether or not the events did — as
  // does the periodic one ten seconds later, if this one is dropped too.
  publishState(nowMs);
}

void CourtBox::noteAuthLapse(uint32_t nowMs) {
  if (auth_.lapsed(nowMs)) {
    static_cast<void>(sendFrame(proto::Frame::evt("AUTHEXPIRED", "")));
    showIdle();
  }
}

void CourtBox::flushOverrun() {
  if (!overrunPending_) {
    return;
  }
  // Clear first. sendFrame() sets the flag again if this attempt also fails,
  // so a link that is still full simply retries next pass instead of the flag
  // being cleared by a send that did not happen.
  overrunPending_ = false;
  static_cast<void>(sendFrame(proto::Frame::evt("OVERRUN", "TX")));
}

void CourtBox::publishState(uint32_t nowMs) {
  const uint8_t mask = relays_.mask();
  if (mask == lastMask_ && !stateDue_.expired(nowMs)) {
    return;
  }
  lastMask_ = mask;
  stateDue_.arm(nowMs, kStateIntervalMs);

  uint16_t remaining[hal::kRelayChannelCount];
  for (uint8_t i = 0U; i < hal::kRelayChannelCount; ++i) {
    remaining[i] = relays_.remainingSeconds(i, nowMs);
  }
  static_cast<void>(sendFrame(proto::Frame::state(mask, remaining)));
}

// --- inbound ---------------------------------------------------------------

void CourtBox::handleResult(const proto::Decoder::Result& result, uint32_t nowMs) {
  if (result.isFrame()) {
    handleFrame(result.frame, nowMs);
    return;
  }
  if (rxErrors_ < UINT16_MAX) {
    ++rxErrors_;
  }
  reportDecodeError(result.error);
}

void CourtBox::handleFrame(const proto::Frame& frame, uint32_t nowMs) {
  // An if-chain rather than a switch. -Wswitch-enum requires every one of the
  // fourteen verbs to be listed even with a default, which is a fourteen-case
  // switch scoring CCN 15 — the complexity gate's limit exactly — to dispatch
  // the seven verbs that travel in this direction.
  const proto::Verb verb = frame.verb();
  if (verb == proto::Verb::On) {
    applyOn(frame, nowMs);
  } else if (verb == proto::Verb::Off) {
    applyOff(frame);
  } else if (verb == proto::Verb::Ext) {
    applyExt(frame, nowMs);
  } else if (verb == proto::Verb::Lcd) {
    // The bridge answered, so its text stands and the local feedback must not
    // repaint idle over it ten seconds later.
    scanFeedback_.disarm();
    paintRow(0U, frame.arg(0));
    paintRow(1U, frame.arg(1));
  } else if (verb == proto::Verb::Auth) {
    auth_.arm(nowMs, parseU32(frame.arg(0)));
  } else if (verb == proto::Verb::Rst) {
    begin();
  } else if (verb == proto::Verb::Ping) {
    static_cast<void>(sendFrame(proto::Frame::pong(fw::kFirmwareVersion, uptimeSeconds())));
  } else {
    // A well-formed uplink verb arriving on the downlink. The peer is confused
    // about which direction it is talking in, which is worth saying out loud
    // rather than ignoring: it is what a crossed TX/RX pair looks like.
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::BadVerb)));
  }
}

void CourtBox::reportDecodeError(proto::DecodeError error) {
  // BADFRAME and OVERRUN are `!EVT` names; the other four are `!ERR` codes.
  // Both spellings come from proto::errorName(), so the wire strings cannot
  // drift from the enum.
  if (error == proto::DecodeError::BadFrame || error == proto::DecodeError::Overrun) {
    static_cast<void>(sendFrame(proto::Frame::evt(proto::errorName(error), "RX")));
    return;
  }
  if (error != proto::DecodeError::None) {
    static_cast<void>(sendFrame(proto::Frame::err(error)));
  }
}

void CourtBox::applyOn(const proto::Frame& frame, uint32_t nowMs) {
  proto::Court court = proto::Court::A;
  if (!proto::courtFromChar(frame.arg(0)[0], court)) {
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::NoCourt)));
    return;
  }
  static_cast<void>(relays_.on(static_cast<uint8_t>(court), parseU32(frame.arg(1)), nowMs));
  publishState(nowMs);
}

void CourtBox::applyOff(const proto::Frame& frame) {
  proto::Court court = proto::Court::A;
  if (!proto::courtFromChar(frame.arg(0)[0], court)) {
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::NoCourt)));
    return;
  }
  static_cast<void>(relays_.off(static_cast<uint8_t>(court)));

  // Report it, the same way an expiry is reported.
  //
  // A commanded OFF released a court and told nobody. The bridge has always
  // accepted `!EVT,OFF,<court>` — handleMegaEvent tests for it by name — but the
  // Mega only ever sent AUTOOFF, so a member who finished early and pressed the
  // release button produced no release event at all. The session then looked to
  // the club like it had run its full booked length, which is the opposite of
  // what the Mega's timer exists to record: the court was used for the time it
  // was used, not for the time it was booked.
  //
  // The relay is already open when this is sent, so an event that fails to
  // encode cannot leave the court lit.
  sendCourtEvent("OFF", court);

  // No publishState() here: the caller's pass ends with one, and an OFF that
  // is immediately followed by the periodic frame would put two `!STATE` on a
  // 9600 baud link for one change.
}

void CourtBox::applyExt(const proto::Frame& frame, uint32_t nowMs) {
  proto::Court court = proto::Court::A;
  if (!proto::courtFromChar(frame.arg(0)[0], court)) {
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::NoCourt)));
    return;
  }
  if (!relays_.extend(static_cast<uint8_t>(court), parseU32(frame.arg(1)), nowMs)) {
    // The relay is open. Refusing is the spec's rule; saying so is what stops
    // the bridge believing it extended a session that had already ended.
    static_cast<void>(sendFrame(proto::Frame::err(proto::DecodeError::BadArg)));
  }
}

// --- outbound --------------------------------------------------------------

bool CourtBox::sendFrame(const proto::Frame& frame) {
  const size_t len = proto::encode(frame, txBuf_, sizeof(txBuf_));
  if (len == 0U || !bridge_.connected() || bridge_.writable() < len) {
    if (txDropped_ < UINT16_MAX) {
      ++txDropped_;
    }
    overrunPending_ = true;
    return false;
  }
  // encode() already appended the '\n', so this is not hal::writeLine()'s job:
  // that helper terminates a C string, and the encoder's output is a byte count
  // that is not NUL-terminated. Going through it would put two terminators on
  // the wire and turn every frame into a frame plus an empty line.
  const size_t wrote = bridge_.write(reinterpret_cast<const uint8_t*>(txBuf_), len);
  if (wrote != len) {
    // writable() is advisory (hal/Transport.h says so), so a fragment may
    // already be on the wire. The peer's checksum catches it; the count is how
    // anyone finds out it is happening.
    if (txDropped_ < UINT16_MAX) {
      ++txDropped_;
    }
    overrunPending_ = true;
    return false;
  }
  return true;
}

void CourtBox::sendCourtEvent(const char* name, proto::Court court) {
  const char detail[2] = {proto::courtChar(court), '\0'};
  static_cast<void>(sendFrame(proto::Frame::evt(name, detail)));
}

void CourtBox::paintRow(uint8_t row, const char* text) {
  char padded[hal::kDisplayCols + 1U];
  uint8_t i = 0U;
  while (i < hal::kDisplayCols && text[i] != '\0') {
    padded[i] = text[i];
    ++i;
  }
  while (i < hal::kDisplayCols) {
    padded[i] = ' ';
    ++i;
  }
  padded[hal::kDisplayCols] = '\0';
  display_.print(row, 0U, padded);
}

void CourtBox::showIdle() {
  paintRow(0U, kIdleLine1);
  paintRow(1U, kIdleLine2);
}

} // namespace courtlogic
